<?php declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Senate\SubordinatePersonaReconciliationOpeningService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Output\OutputInterface;#[AsCommand(name:'imperium:senate:open-subordinate-persona-reconciliation')]final class SenateOpenSubordinatePersonaReconciliationCommand extends Command{public function __construct(private readonly SubordinatePersonaReconciliationOpeningService$s){parent::__construct();}protected function configure():void{$this->addArgument('security-finding-id',InputArgument::REQUIRED);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->open((string)$i->getArgument('security-finding-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln('<info>PERSONA_FINDINGS_ADMITTED_UNCHANGED_RECONCILIATION_AUTHORITY_OPENED</info> '.$r['reconciliation_opening_id']);return self::SUCCESS;}}
